import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Integrations — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"integrations-01-overview-and-concepts.md","filePath":"integrations-01-overview-and-concepts.md"}'),o={name:"integrations-01-overview-and-concepts.md"};function s(r,t,d,l,c,h){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="integrations-—-overview-concepts" tabindex="-1">Integrations — Overview &amp; Concepts <a class="header-anchor" href="#integrations-—-overview-concepts" aria-label="Permalink to &quot;Integrations — Overview &amp; Concepts&quot;">​</a></h1><p><em>What integrations do, why they exist, and how Lodestone thinks about connected systems</em></p><hr><h2 id="the-philosophy-behind-integrations" tabindex="-1">The Philosophy Behind Integrations <a class="header-anchor" href="#the-philosophy-behind-integrations" aria-label="Permalink to &quot;The Philosophy Behind Integrations&quot;">​</a></h2><p>Lodestone integrations are built around a single guiding principle:</p><blockquote><p>Product planning and communication live in Lodestone. Execution and operational work live elsewhere.</p></blockquote><p>Integrations exist to eliminate redundant effort — not to consolidate everything into one system. Lodestone doesn&#39;t aim to replace your delivery tools, CRM, or recording platform. It aims to work alongside them, so data flows between systems without you having to manually maintain both.</p><hr><h2 id="what-lives-where" tabindex="-1">What Lives Where <a class="header-anchor" href="#what-lives-where" aria-label="Permalink to &quot;What Lives Where&quot;">​</a></h2><p>Understanding which system owns which data is the foundation of any integration decision:</p><h3 id="lives-in-lodestone" tabindex="-1">Lives in Lodestone <a class="header-anchor" href="#lives-in-lodestone" aria-label="Permalink to &quot;Lives in Lodestone&quot;">​</a></h3><ul><li>Features, Roadmaps, Releases, Strategies, Documents, Auctions</li><li>Product intent, planning context, and communication artifacts</li></ul><h3 id="lives-in-external-systems" tabindex="-1">Lives in external systems <a class="header-anchor" href="#lives-in-external-systems" aria-label="Permalink to &quot;Lives in external systems&quot;">​</a></h3><ul><li>Developer tickets and delivery tasks (JIRA)</li><li>Call recordings and transcripts (Fireflies, Gong)</li><li>CRM activity, support tickets, and customer data (Salesforce, Zendesk, etc.)</li></ul><p>Lodestone integrates with these systems but doesn&#39;t absorb them. Each tool remains the source of truth for its own domain.</p><hr><h2 id="data-flow-in-and-out" tabindex="-1">Data Flow: In and Out <a class="header-anchor" href="#data-flow-in-and-out" aria-label="Permalink to &quot;Data Flow: In and Out&quot;">​</a></h2><p>Integrations move data in two directions:</p><h3 id="into-lodestone" tabindex="-1">Into Lodestone <a class="header-anchor" href="#into-lodestone" aria-label="Permalink to &quot;Into Lodestone&quot;">​</a></h3><ul><li>Meeting transcripts → Extracts module (Fireflies, Gong)</li><li>Feature status updates from delivery tools (JIRA)</li><li>In the future: customer quotes, problems and opportunities from CRM and support systems</li></ul><h3 id="out-of-lodestone" tabindex="-1">Out of Lodestone <a class="header-anchor" href="#out-of-lodestone" aria-label="Permalink to &quot;Out of Lodestone&quot;">​</a></h3><ul><li>New Features created in Lodestone → JIRA issues</li><li>Feature updates and status changes → JIRA</li><li>In the future: User Stories exported to JIRA</li></ul><p>The goal is to remove double-entry while keeping product intent and context centralized in Lodestone.</p><hr><h2 id="live-integrations" tabindex="-1">Live Integrations <a class="header-anchor" href="#live-integrations" aria-label="Permalink to &quot;Live Integrations&quot;">​</a></h2><p>Lodestone currently has eight live integrations:</p><table tabindex="0"><thead><tr><th>Integration</th><th>Purpose</th><th>Module</th></tr></thead><tbody><tr><td>Fireflies</td><td>Transcript ingestion with configurable auto-sync</td><td>Extracts</td></tr><tr><td>Gong</td><td>Transcript ingestion with configurable auto-sync + CRM metadata enrichment</td><td>Extracts</td></tr><tr><td>Fathom</td><td>Transcript ingestion with configurable auto-sync</td><td>Extracts</td></tr><tr><td>Granola</td><td>Meeting notes ingestion with configurable auto-sync</td><td>Extracts</td></tr><tr><td>tl;dv</td><td>Transcript ingestion with configurable auto-sync</td><td>Extracts</td></tr><tr><td>JIRA</td><td>Delivery synchronization</td><td>Features, Releases</td></tr><tr><td>Asana</td><td>Delivery synchronization</td><td>Backlog</td></tr><tr><td>Lodestone API &amp; MCP</td><td>Programmatic access and AI agent connectivity</td><td>All modules</td></tr></tbody></table><p>Fireflies, Gong, Fathom, Granola, and tl;dv are discovery integrations — they bring signal in. JIRA and Asana are delivery integrations — they keep Backlog item and status data in sync with your engineering workflow. The Lodestone API &amp; MCP enables external tools, automation, and AI assistants (including custom Claude and ChatGPT configurations) to read and write Lodestone data.</p><p>All five transcript integrations support <strong>automatic sync</strong> — Lodestone can pull new transcripts and meeting notes on a configurable schedule (every 12 hours, 24 hours, or weekly) rather than requiring a manual import each time.</p><h3 id="gong-crm-enrichment" tabindex="-1">Gong CRM Enrichment <a class="header-anchor" href="#gong-crm-enrichment" aria-label="Permalink to &quot;Gong CRM Enrichment&quot;">​</a></h3><p>In addition to transcript ingestion, the Gong integration enriches extracted features with CRM context. When a Gong call is imported, Lodestone automatically attaches metadata from the associated Gong account — such as company name and revenue data — to the extracted features as context. This surfaces customer business context alongside the product signal, helping you distinguish high-value signals from noise.</p><hr><h2 id="who-can-manage-integrations" tabindex="-1">Who Can Manage Integrations <a class="header-anchor" href="#who-can-manage-integrations" aria-label="Permalink to &quot;Who Can Manage Integrations&quot;">​</a></h2><p>Any workspace member can connect and configure integrations — it is not restricted to admins. Integration settings are found in Settings &gt; Integrations.</p><hr><h2 id="planned-integrations" tabindex="-1">Planned Integrations <a class="header-anchor" href="#planned-integrations" aria-label="Permalink to &quot;Planned Integrations&quot;">​</a></h2><p>Lodestone is actively expanding its integration surface. Integrations in progress or planned include:</p><h3 id="crm-and-support-systems" tabindex="-1">CRM and support systems <a class="header-anchor" href="#crm-and-support-systems" aria-label="Permalink to &quot;CRM and support systems&quot;">​</a></h3><ul><li>Salesforce</li><li>Zendesk</li><li>Freshdesk</li></ul><p>These will expand transcript ingestion and customer signal into Extracts, with the ability to attach customer metadata (company name, contact, ARR/MRR) to ideas surfaced from conversations.</p><h3 id="delivery-and-ticketing-systems" tabindex="-1">Delivery and ticketing systems <a class="header-anchor" href="#delivery-and-ticketing-systems" aria-label="Permalink to &quot;Delivery and ticketing systems&quot;">​</a></h3><ul><li>Azure DevOps</li></ul><p>These will bring the same delivery synchronization currently available with JIRA and Asana to teams using other tools.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for connecting Fireflies, Gong, JIRA, and Asana.</em></p>',45)])])}const p=e(o,[["render",s]]);export{g as __pageData,p as default};
